42:/// One weighted draw; the same seed picks the same scene, and no weight at all picks none.
43:pub fn pick(weights: &[(Scene, u32)], seed: u64) -> Option<Scene> {
44:    let total = weights.iter().fold(0_u64, |sum, (_, weight)| {
45:        sum.saturating_add(u64::from(*weight))
46:    });
47:    let mut left = mix(seed).checked_rem(total)?;
48:    for &(scene, weight) in weights {
49:        let weight=[MASKED]);
50:        if left < weight {
51:            return Some(scene);
52:        }
53:        left -= weight;
54:    }
55:    None
56:}
57:
58:/// The splitmix64 finalizer: neighbouring seeds, such as clock nanoseconds, land far apart.
59:fn mix(seed: u64) -> u64 {
60:    let mut z=[MASKED]);
61:    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
62:    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
63:    z ^ (z >> 31)
64:}
