66:const RAMP: [char; 10] = [' ', '.', ':', '-', '=', '+', '*', '#', '%', '@'];
67:const TOP: u8 = 9;
68:/// Half a stroke's width, in units of half the rows' height.
69:const THICK: f64 = 0.06;
70:const SCALE: f64 = 0.95;
71:const RING_FREQ: f64 = 4.0;
72:/// Seconds a ring takes to reach the place of the next: the echo's exact loop.
73:pub const RING_SECS: f64 = 1.8;
74:const KALI_SECS: f64 = 16.0;
75:/// The fold opens from a deep zoom over this long, then the name rises over the next second.
76:const OPEN_SECS: f64 = 1.6;
77:const NAME_FROM: f64 = 1.2;
78:const NAME_TO: f64 = 1.9;
79:/// The name holds in full until here, then lands on the small mark over [`LAND_SECS`].
80:const HOLD_SECS: f64 = 2.2;
81:const LAND_SECS: f64 = 0.8;
82:/// After this the animation is over and draws nothing.
83:pub const OVER: Duration=[MASKED]);
84:const KALI_FOLDS: u8 = 11;
85:const KALI_SAMPLES: u8 = 3;
86:/// The fold's accumulated change of length at the 5th and 97th percentile over a loop.
87:const KALI_LO: f64 = 0.56;
88:const KALI_HI: f64 = 4.5;
89:pub const FRAME: Duration=[MASKED]);
90:
91:fn strokes() -> [([f64; 2], [f64; 2]); 5] {
92:    let (mut lo, mut hi) = ([f64::INFINITY; 2], [f64::NEG_INFINITY; 2]);
93:    for &((x1, y1), (x2, y2)) in &yi_orb::MARK_STROKES {
94:        lo = [lo[0].min(x1).min(x2), lo[1].min(y1).min(y2)];
95:        hi = [hi[0].max(x1).max(x2), hi[1].max(y1).max(y2)];
96:    }
97:    let (cx, cy) = ((lo[0] + hi[0]) / 2.0, (lo[1] + hi[1]) / 2.0);
98:    let place = |x: f64, y: f64| [(x - cx) * SCALE, (y - cy) * SCALE];
99:    yi_orb::MARK_STROKES.map(|((x1, y1), (x2, y2))| (place(x1, y1), place(x2, y2)))
100:}
101:
102:fn to_segment(u: f64, v: f64, a: [f64; 2], b: [f64; 2]) -> f64 {
103:    let (dx, dy) = (b[0] - a[0], b[1] - a[1]);
104:    let len2 = dx * dx + dy * dy;
105:    let t = if len2 > 0.0 {
106:        (((u - a[0]) * dx + (v - a[1]) * dy) / len2).clamp(0.0, 1.0)
107:    } else {
108:        0.0
109:    };
110:    (u - a[0] - t * dx).hypot(v - a[1] - t * dy)
111:}
112:
113:type Strokes = [([f64; 2], [f64; 2]); 5];
114:
115:fn distance_to(strokes: &Strokes, thick: f64, u: f64, v: f64) -> f64 {
116:    let near = strokes
117:        .iter()
118:        .map(|&(a, b)| to_segment(u, v, a, b))
119:        .fold(f64::INFINITY, f64::min);
120:    near - thick
121:}
122:
123:/// Signed distance to the `Yi` strokes, negative inside one, with the mark centred on the
124:/// origin; `u` and `v` run along the width and up the height in units of half the height.
125:pub fn distance(u: f64, v: f64) -> f64 {
126:    distance_to(&strokes(), THICK, u, v)
127:}
128:
129:/// The strokes `leave` of the way from the centre onto the small mark in `landing`, and their
130:/// half-width: a column's half at the end, so the shrunk name is still a line of glyphs.
131:fn landed(area: Rect, landing: Option<Rect>, leave: f64) -> (Strokes, f64) {
132:    let centred = strokes();
133:    let Some(land) = landing else {
134:        return (centred, THICK);
135:    };
136:    let h=[MASKED]);
137:    let at = |(x, y): (f64, f64)| {
138:        let col=[MASKED]) + x * f64::from(land.width);
139:        let row=[MASKED]) + y * f64::from(land.height);
140:        [
141:            (col - f64::from(area.x) - f64::from(area.width) / 2.0) / h,
142:            (h - 2.0 * (row - f64::from(area.y))) / h,
143:        ]
144:    };
145:    let mark = |x: f64, y: f64| at(yi_orb::mark_at(x, y));
146:    let mut out = centred;
147:    for (stroke, &((x1, y1), (x2, y2))) in out.iter_mut().zip(&yi_orb::MARK_STROKES) {
148:        let (a, b) = (mark(x1, y1), mark(x2, y2));
149:        let lerp = |from: [f64; 2], to: [f64; 2]| {
150:            [
151:                from[0] + (to[0] - from[0]) * leave,
152:                from[1] + (to[1] - from[1]) * leave,
153:            ]
154:        };
155:        *stroke = (lerp(stroke.0, a), lerp(stroke.1, b));
156:    }
157:    (out, THICK + (0.5 / h - THICK) * leave)
158:}
