160:fn echo(d: f64, t: f64) -> f64 {
161:    let ring = 0.5 + 0.5 * (TAU * (d.max(0.0) * RING_FREQ - (t % RING_SECS) / RING_SECS)).cos();
162:    ring * ring * (-0.9 * d.max(0.0)).exp()
163:}
164:
165:fn fold(mut x: f64, mut y: f64, cx: f64, cy: f64) -> f64 {
166:    let mut prev = x.hypot(y);
167:    let mut total = 0.0;
168:    for _ in 0..KALI_FOLDS {
169:        let r2 = x * x + y * y + 1e-9;
170:        x = x.abs() / r2 - cx;
171:        y = y.abs() / r2 - cy;
172:        let len = x.hypot(y);
173:        total += (len - prev).abs();
174:        prev = len;
175:    }
176:    total / f64::from(KALI_FOLDS)
177:}
