179:/// The Kali fold at `(u, v)`, each cell averaged over `du` by `dv` of samples: the plane turns
180:/// once a loop while `c` circles and the scale breathes; the first seconds zoom out of the fold.
181:fn kali(u: f64, v: f64, (du, dv): (f64, f64), frame: &KaliFrame) -> f64 {
182:    let KaliFrame {
183:        sin,
184:        cos,
185:        c: (cx, cy),
186:        scale,
187:        fade,
188:    } = *frame;
189:    let n=[MASKED]);
190:    let mut sum = 0.0;
191:    for j in 0..KALI_SAMPLES {
192:        for i in 0..KALI_SAMPLES {
193:            let su = u + ((f64::from(i) + 0.5) / n - 0.5) * du;
194:            let sv = v + ((f64::from(j) + 0.5) / n - 0.5) * dv;
195:            sum += fold(
196:                (su * cos - sv * sin) * scale,
197:                (su * sin + sv * cos) * scale,
198:                cx,
199:                cy,
200:            );
201:        }
202:    }
203:    let raw = sum / (n * n);
204:    ((raw - KALI_LO) / (KALI_HI - KALI_LO))
205:        .clamp(0.0, 1.0)
206:        .powf(1.1)
207:        * fade
208:}
