210:/// What the fold shares across every cell of one frame.
211:#[derive(Clone, Copy)]
212:struct KaliFrame {
213:    sin: f64,
214:    cos: f64,
215:    c: (f64, f64),
216:    scale: f64,
217:    fade: f64,
218:}
219:
220:impl KaliFrame {
221:    fn at(t: f64) -> Self {
222:        let (sin, cos) = (TAU * t / KALI_SECS).sin_cos();
223:        Self {
224:            sin,
225:            cos,
226:            c: (0.80 + 0.03 * sin, 0.55 + 0.03 * cos),
227:            scale: 0.5 * (1.0 + 0.18 * sin) * (0.3 + 0.7 * smooth(t / OPEN_SECS)),
228:            fade: smooth(t / 0.3),
229:        }
230:    }
231:}
