233:/// Cells farther than this from every stroke cannot see the extruded name.
234:const SOLID_NEAR: f64 = 0.45;
235:
236:/// The name as a lit extrusion, sphere-traced from a camera that swings once while it holds;
237:/// `None` where the ray misses. It shrinks onto the small mark with the same strokes.
238:fn solid(strokes: &Strokes, thick: f64, (u, v): (f64, f64), t: f64, leave: f64) -> Option<f64> {
239:    let half_z = 0.17 * smooth((t - 0.3) / 0.9) * (1.0 - 0.85 * leave);
240:    if half_z < 0.01 {
241:        return None;
242:    }
243:    let fat = 0.05 * (1.0 - leave);
244:    let (sin, cos) = (0.55 * (PI * t / HOLD_SECS).sin() * (1.0 - leave)).sin_cos();
245:    let f =
246:        |x: f64, y: f64, z: f64| (distance_to(strokes, thick, x, y) - fat).max(z.abs() - half_z);
247:    let eye = [-3.0 * sin, 0.0, -3.0 * cos];
248:    let aim = [u * cos + 3.0 * sin, v, -u * sin + 3.0 * cos];
249:    let len = (aim[0] * aim[0] + aim[1] * aim[1] + aim[2] * aim[2]).sqrt();
250:    let dir = aim.map(|c| c / len);
251:    let mut at = 0.0;
252:    for _ in 0..40 {
253:        let p = [
254:            eye[0] + dir[0] * at,
255:            eye[1] + dir[1] * at,
256:            eye[2] + dir[2] * at,
257:        ];
258:        let d = f(p[0], p[1], p[2]);
259:        if d < 0.006 {
260:            let e = 0.012;
261:            let n = [
262:                f(p[0] + e, p[1], p[2]) - f(p[0] - e, p[1], p[2]),
263:                f(p[0], p[1] + e, p[2]) - f(p[0], p[1] - e, p[2]),
264:                f(p[0], p[1], p[2] + e) - f(p[0], p[1], p[2] - e),
265:            ];
266:            let size = (n[0] * n[0] + n[1] * n[1] + n[2] * n[2]).sqrt().max(1e-9);
267:            let lum = (n[0] * -0.45 + n[1] * 0.65 + n[2] * -0.6) / size;
268:            return Some(0.30 + 0.70 * lum.max(0.0));
269:        }
270:        at += d * 0.9;
271:        if at > 6.0 {
272:            return None;
273:        }
274:    }
275:    None
276:}
