278:/// Dim the field near the strokes and fill them: `rise` 0 leaves the field, 1 is the name.
279:fn name(field: f64, d: f64, rise: f64) -> f64 {
280:    if d < 0.0 {
281:        field + (1.0 - field) * rise
282:    } else {
283:        field * (1.0 - rise * 0.85 * (-9.0 * d).exp())
284:    }
285:}
