287:/// A cell is twice as tall as wide, so a row spans two units of `v` where a column spans one
288:/// of `u`, both over the height.
289:fn at(x: u16, y: u16, width: u16, height: u16) -> (f64, f64) {
290:    let h=[MASKED]);
291:    let u = (f64::from(x) + 0.5 - f64::from(width) / 2.0) / h;
292:    let v = (h - 2.0 * f64::from(y) - 1.0) / h;
293:    (u, v)
294:}
