296:fn style(step: usize, theme: &Theme) -> Style {
297:    match step {
298:        0..=4 => theme.dim_style(),
299:        5..=7 => theme.accent_style(),
300:        _ => theme.accent_style().add_modifier(Modifier::BOLD),
301:    }
302:}
