304:/// A cell's seed in `0.0..1.0`, fixed per place: which cells give the screen back first.
305:fn dissolve(x: u16, y: u16) -> f64 {
306:    let h = (u32::from(x).wrapping_mul(73_856_093) ^ u32::from(y).wrapping_mul(19_349_663))
307:        .wrapping_mul(2_654_435_761);
308:    f64::from(h >> 8) / 16_777_216.0
309:}
