311:/// Cover every cell of `area` with `scene` until [`OVER`]. From [`HOLD_SECS`] the name shrinks onto
312:/// `landing` and the cells around it give the screen back a few at a time.
313:pub fn cover(
314:    buffer: &mut Buffer,
315:    area: Rect,
316:    (scene, elapsed): (Scene, Duration),
317:    landing: Option<Rect>,
318:    theme: &Theme,
319:) {
320:    if elapsed >= OVER {
321:        return;
322:    }
323:    let t=[MASKED]);
324:    let h=[MASKED]);
325:    let cell = (1.0 / h, 2.0 / h);
326:    let turn = KaliFrame::at(t);
327:    let rise = match scene {
328:        Scene::Kali => smooth((t - NAME_FROM) / (NAME_TO - NAME_FROM)),
329:        Scene::Echo => 1.0,
330:        Scene::Solid => 0.0,
331:    };
332:    let leave = smooth((t - HOLD_SECS) / LAND_SECS);
333:    let fade = 1.0 - smooth(leave * 1.25);
334:    let reveal = smooth((leave - 0.1) / 0.9);
335:    let (strokes, thick) = landed(area, landing, leave);
336:    for y in 0..area.height {
337:        for x in 0..area.width {
338:            let (u, v) = at(x, y, area.width, area.height);
339:            let d=[MASKED], thick, u, v);
340:            let solid_hit = match scene {
341:                Scene::Solid if d < SOLID_NEAR => solid(&strokes, thick, (u, v), t, leave),
342:                _ => None,
343:            };
344:            let in_name = match scene {
345:                Scene::Solid => solid_hit.is_some(),
346:                _ => d < 0.0,
347:            };
348:            if !in_name && dissolve(x, y) < reveal {
349:                continue;
350:            }
351:            let field = match scene {
352:                _ if fade <= 0.0 => 0.0,
353:                Scene::Kali => kali(u, v, cell, &turn) * fade,
354:                Scene::Echo => echo(d, t) * fade,
355:                Scene::Solid => echo(d.max(0.1), t) * fade * 0.6,
356:            };
357:            let value = match solid_hit {
358:                Some(lit) => lit,
359:                None => name(field, d, rise),
360:            }
361:            .clamp(0.0, 1.0);
362:            let step=[MASKED] * f64::from(TOP)).round() as u8);
363:            let place=[MASKED]), area.y.saturating_add(y));
364:            if let Some(target) = buffer.cell_mut(place) {
365:                target.reset();
366:                if let (Some(glyph), true) = (RAMP.get(step), step > 0) {
367:                    target.set_char(*glyph).set_style(style(step, theme));
368:                }
369:            }
370:        }
371:    }
372:}
